/* Armenian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Armen": "Armenian — Armenian", "Anahit": "The ancient goddess of fertility and wisdom; a beloved feminine name.", "Tigran": "The name of the great king Tigran the Great.", "Narek": "A name from the holy monastery of Narek.", "Aram": "The legendary patriarch of the Armenians.", "Gayane": "The name of St. Gayane, martyred virgin of Armenia.", "Hovhannisyan": "The most Armenian surname form: son of John.", "Grigoryan": "A classic -yan surname.", "Sargsyan": "Family name of Serzh Sargsyan, former president of Armenia.", "Khachaturian": "Family name of Aram Khachaturian, the great composer."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Armen';
console.log(lookup(q));

